LOG_RE = re.compile(
    r'^(?P<ip>\S+)\s+\S+\s+\S+\s+\[(?P<dt>[^\]]+)\]\s+"(?P<req>[^"]*)"\s+(?P<status>\d{3})\s+(?P<bytes>\d+)\s+"(?P<ref>[^"]*)"'
)
DT_RE = re.compile(r'^(\d{1,2})/([A-Za-z]{3})/(\d{4}):(\d{2}):(\d{2}):(\d{2})\s+[+-]\d{4}$')

@dataclass
class Hit:
    raw: str
    dt: datetime
    ip: str
    method: str
    path: str
    status: str
    bytes: int
    referer: str
    file_index: int = 0
    line_index: int = 0

    @property
    def date_s(self) -> str:
